await cdp('Network.enable');await cdp('Network.setCacheDisabled',{cacheDisabled:true});await cdp('Network.setBlockedURLs',{urls:['*fonts.googleapis.com*','*fonts.gstatic.com*']});
const delay=async()=>{await new Promise(r=>setTimeout(r,600));for(let n=0;n<80;n++){const r=await ev('document.body.classList.contains("buyer-app")&&!document.querySelector("#main").innerText.includes("Đang tải")&&!document.querySelector("#main").innerText.includes("Đang xử lý thanh toán demo")');if(r.value)return;await new Promise(r=>setTimeout(r,150));}throw Error('Page did not finish loading')};
const E=async x=>{const r=await ev(x);if(r.subtype==='error')throw Error(r.description);return r.value;};
const check=async(label,x)=>{if(!await E(x))throw Error('FAIL '+label+' '+await E('document.body.innerText.slice(-1200)'));console.log('PASS',label)};
const fill=async(name,data)=>{await E('(()=>{const f=document.querySelector('+JSON.stringify('form[data-form="'+name+'"]')+');if(!f)throw Error("Missing form '+name+'");for(const [k,v] of Object.entries('+JSON.stringify(data)+')){const el=f.elements[k];if(!el)throw Error("Missing "+k);if(el.type==="checkbox")el.checked=v;else el.value=v;el.dispatchEvent(new Event("input",{bubbles:true}));}f.requestSubmit();})()');await delay();};
const click=async(action,id)=>{await E('document.querySelector('+JSON.stringify('[data-action="'+action+'"]'+(id?'[data-id="'+id+'"]':''))+').click()');await delay();};
const confirm=async()=>{await E('document.querySelector("#confirm button[value=ok]").click()');await delay();};
const state=async()=>JSON.parse(await E('localStorage.getItem("pcmatch-demo-v2")'));
await nav('index.html');await E(`(()=>{const input=document.querySelector('input[type=search]');input.value='B45';input.dispatchEvent(new Event('input',{bubbles:true}));})()`);await check('sitemap search finds B45',`document.querySelectorAll('.screen-link:not([hidden])').length===1`);await E(`(()=>{const input=document.querySelector('input[type=search]');input.value='no-match-zz';input.dispatchEvent(new Event('input',{bubbles:true}));})()`);await check('sitemap no-results recovery','document.body.innerText.includes("Không tìm thấy màn hình")');
await nav('buyer/orders.html');await delay();const order=(await state()).orders[0];if(!order)throw Error('Run purchase-flows first for the order fixture');await E(`(async()=>{const s=await import('/assets/js/store.js');s.tx(d=>{d.orders[0].payment='paid';d.orders[0].suborders[0].status='Chờ shop xác nhận';d.orders[0].suborders[0].shippingStatus='Chưa tạo vận đơn';});})()`);await nav('buyer/order.html?id='+order.id);await delay();const sub=order.suborders[0];await check('only next delivery milestone initially','!!document.querySelector("[data-action=order-confirm]")&&!document.querySelector("[data-action=order-delivered]")');await click('order-confirm',sub.id);await click('order-ship',sub.id);await click('order-failed',sub.id);await click('order-returning',sub.id);await click('order-returned',sub.id);await check('returned shipment does not create refund or reset status','!JSON.parse(localStorage.getItem("pcmatch-demo-v2")).orders[0].suborders[0].refund&&document.body.innerText.includes("Đã hoàn hàng")&&!document.querySelector("[data-action=order-confirm]")');
await check('refund rounding never exceeds allocated discount',`(async()=>{const {discountForSerials}=await import('/assets/js/aftersale-data.js');const item={id:'i',qty:3,price:100,serials:['a','b','c']};const sub={subtotal:300,discount:100,items:[item]};return ['a','b','c'].reduce((sum,n)=>sum+discountForSerials(sub,item,[n]),0)===100})()`);
